cd /home/vscode/nullness-benchmarks/libgdx && sed -i '50,60s/container.setActor(newLabel(text, style.label));/if (style.label == null) throw new NullPointerException("style.label cannot be null");
    container.setActor(newLabel(text, style.label));/' gdx/src/com/badlogic/gdx/scenes/scene2d/ui/TextTooltip.java && sed -i '71,77s/Label label = container.getActor();/Label label = container.getActor();
